/**
 * @method
 * @name dts_FaxLink_OnLoadError
 * @description dts_FaxLink 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_FaxLink_OnLoadError = async function() {
    try {
        // CloseWin(-1, grd_FaxLink);
        await $c.win.alert(dts_FaxLink);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20700.dts_FaxLink_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_FaxLink_OnLoadCompleted
 * @description dts_FaxLink 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_FaxLink_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_FaxLink.errorMsg) {
            await $c.win.alert(dts_FaxLink.errorMsg);
        }
        // CloseWin(rowcount, grd_FaxLink);

        // 그리드에 건수 표기.
        scwin.setGrdTitle("ins_Search");

        // 발행기관신청목록 조회
        await scwin.ins_search1();

        // 표준코드 신청목록 조회
        await scwin.ins_search2();

        // 다운로드목록조회
        await scwin.ins_search3();

        // 표준코드 삭제신청목록 조회
        await scwin.ins_search4();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20700.dts_FaxLink_OnLoadCompleted" });
    }
};

