/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        if (trs_Save.Action.indexOf("registerEtcFaxLink1") > -1) {
            // 재조회
            await scwin.ins_search1();
        } else if (trs_Save.Action.indexOf("registerEtcFaxLink2") > -1) {
            // 재조회
            await scwin.ins_search2();
        } else if (trs_Save.Action.indexOf("registerEtcFaxLink3") > -1) {
            // 재조회
            await scwin.ins_search3();
        } else if (trs_Save.Action.indexOf("registerEtcFaxLink4") > -1) {
            // 재조회
            await scwin.ins_search4();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20700.trs_Save_OnSuccess" });
    }
};

