/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FROM_RCV_DD.setValue(vCurDate);
    edt_TO_RCV_DD.setValue(vCurDate);
    edt_FROM_ISUR_APPL_DD.setValue(vCurDate);
    edt_TO_ISUR_APPL_DD.setValue(vCurDate);
    edt_FROM_STD_CD_APPL_DD.setValue(vCurDate);
    edt_TO_STD_CD_APPL_DD.setValue(vCurDate);
    edt_FROM_STD_CD_APPL_DD_DEL.setValue(vCurDate);
    edt_TO_STD_CD_APPL_DD_DEL.setValue(vCurDate);
    edt_FROM_PROCS_DD.setValue(vCurDate);
    edt_TO_PROCS_DD.setValue(vCurDate);
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @param {*} pFg pFg
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function(pFg) {
    if (pFg === "ins_search") {
        dts_FaxLink.removeAll();
        dts_IsurAppl.removeAll();
        dts_StdCdAppl.removeAll();
        dts_DownIp.removeAll();
        dts_StdCdAppl_Del.removeAll();
        dts_IsurApplFaxLink.removeAll();
        dts_StdCdApplFaxLink.removeAll();
        dts_DownIpFaxLink.removeAll();
        dts_StdCdApplFaxLink_Del.removeAll();
        scwin.setGrdTitle("ins_Search");
    } else if (pFg === "ins_search1") {
        dts_IsurAppl.removeAll();
        dts_IsurApplFaxLink.removeAll();
        scwin.setGrdTitle("ins_Search1");
    } else if (pFg === "ins_search2") {
        dts_StdCdAppl.removeAll();
        dts_StdCdApplFaxLink.removeAll();
        scwin.setGrdTitle("ins_Search2");
    } else if (pFg === "ins_search3") {
        dts_DownIp.removeAll();
        dts_DownIpFaxLink.removeAll();
        scwin.setGrdTitle("ins_Search3");
    } else if (pFg === "ins_search4") {
        dts_StdCdAppl_Del.removeAll();
        dts_StdCdApplFaxLink_Del.removeAll();
        scwin.setGrdTitle("ins_Search4");
    } else if (pFg === "ins_searchLink1") {
        dts_IsurApplFaxLink.removeAll();
    } else if (pFg === "ins_searchLink2") {
        dts_StdCdApplFaxLink.removeAll();
    } else if (pFg === "ins_searchLink3") {
        dts_DownIpFaxLink.removeAll();
    } else if (pFg === "ins_searchLink4") {
        dts_StdCdApplFaxLink_Del.removeAll();
    }
};

/**
 * @method
 * @name setInsertData
 * @description 파일 연결 시 입력 데이터 세팅
 * @param {*} pGubun pGubun
 * @returns {void}
 * @hidden N
 */
scwin.setInsertData = function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    const fax_img_file_nm = dts_FaxLink.getCellData(dts_FaxLink.getRowPosition(), "FAX_IMG_FILE_NM");
    if (pGubun === "ins_FileLink1") {
        dts_IsurAppl.setBroadcast(false);
        for (let nRow = 1; nRow <= dts_IsurAppl.getRowCount(); nRow++) {
            if (dts_IsurAppl.getCellData(nRow, "CHK") === "T") {
                dts_IsurAppl.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
        dts_IsurAppl.setBroadcast(true, true);
    } else if (pGubun === "ins_FileLink2") {
        dts_StdCdAppl.setBroadcast(false);
        for (let nRow = 1; nRow <= dts_StdCdAppl.getRowCount(); nRow++) {
            if (dts_StdCdAppl.getCellData(nRow, "CHK") === "T") {
                dts_StdCdAppl.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
        dts_StdCdAppl.setBroadcast(true, true);
    } else if (pGubun === "ins_FileLink3") {
        dts_DownIp.setBroadcast(false);
        for (let nRow = 1; nRow <= dts_DownIp.getRowCount(); nRow++) {
            if (dts_DownIp.getCellData(nRow, "CHK") === "T") {
                dts_DownIp.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
        dts_DownIp.setBroadcast(true, true);
    } else if (pGubun === "ins_FileLink4") {
        dts_StdCdAppl_Del.setBroadcast(false);
        for (let nRow = 1; nRow <= dts_StdCdAppl_Del.getRowCount(); nRow++) {
            if (dts_StdCdAppl_Del.getCellData(nRow, "CHK") === "T") {
                dts_StdCdAppl_Del.setCellData(nRow, "FAX_IMG_FILE_NM", fax_img_file_nm);
            }
        }
        dts_StdCdAppl_Del.setBroadcast(true, true);
    }
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    if (pGubun === "ins_Search") {
        if (edt_FROM_RCV_DD.getValue() === "") {
            await $c.win.alert("접수시작일자를 입력하세요.");
            edt_FROM_RCV_DD.focus();
            return false;
        }
        if (edt_TO_RCV_DD.getValue() === "") {
            await $c.win.alert("접수종료일자를 입력하세요.");
            edt_TO_RCV_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_RCV_DD, edt_TO_RCV_DD) === false) {
            return false;
        }
    } else if (pGubun === "ins_search1") {
        if (edt_FROM_ISUR_APPL_DD.getValue() === "") {
            await $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_ISUR_APPL_DD.focus();
            return false;
        }
        if (edt_TO_ISUR_APPL_DD.getValue() === "") {
            await $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_ISUR_APPL_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_ISUR_APPL_DD, edt_TO_ISUR_APPL_DD) === false) {
            return false;
        }
    } else if (pGubun === "ins_search2") {
        if (edt_FROM_STD_CD_APPL_DD.getValue() === "") {
            await $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
        if (edt_TO_STD_CD_APPL_DD.getValue() === "") {
            await $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_STD_CD_APPL_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD, edt_TO_STD_CD_APPL_DD) === false) {
            return false;
        }
    } else if (pGubun === "ins_search3") {
        if (edt_FROM_PROCS_DD.getValue() === "") {
            await $c.win.alert("등록시작일자를 입력하세요.");
            edt_FROM_PROCS_DD.focus();
            return false;
        }
        if (edt_TO_PROCS_DD.getValue() === "") {
            await $c.win.alert("등록종료일자를 입력하세요.");
            edt_TO_PROCS_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_PROCS_DD, edt_TO_PROCS_DD) === false) {
            return false;
        }
    } else if (pGubun === "ins_search4") {
        if (edt_FROM_STD_CD_APPL_DD_DEL.getValue() === "") {
            await $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_STD_CD_APPL_DD_DEL.focus();
            return false;
        }
        if (edt_TO_STD_CD_APPL_DD_DEL.getValue() === "") {
            await $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_STD_CD_APPL_DD_DEL.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD_DEL, edt_TO_STD_CD_APPL_DD_DEL) === false) {
            return false;
        }
    } else if (pGubun === "ins_searchLink1") {
        if (dts_IsurAppl.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun === "ins_searchLink2") {
        if (dts_StdCdAppl.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun === "ins_searchLink3") {
        if (dts_DownIp.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun === "ins_searchLink4") {
        if (dts_StdCdAppl_Del.getRowPosition() < 1) {
            return false;
        }
    } else if (pGubun === "ins_FileLink1") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowCount() === 0) {
            await $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_IsurAppl.getRowCount(); nRow++) {
            if (dts_IsurAppl.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 발행기관신청 정보가 없습니다.");
            return false;
        }
    } else if (pGubun === "ins_FileLink2") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowPosition() < 1) {
            await $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_StdCdAppl.getRowCount(); nRow++) {
            if (dts_StdCdAppl.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 표준코드신청 정보가 없습니다.");
            return false;
        }
    } else if (pGubun === "ins_FileLink3") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowPosition() < 1) {
            await $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_DownIp.getRowCount(); nRow++) {
            if (dts_DownIp.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 다운로드IP 정보가 없습니다.");
            return false;
        }
    } else if (pGubun === "ins_FileLink4") {
        // 조회된 fax가 있는가?
        if (dts_FaxLink.getRowPosition() < 1) {
            await $c.win.alert("조회된 fax정보가 없습니다.");
            return false;
        }

        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_StdCdAppl_Del.getRowCount(); nRow++) {
            if (dts_StdCdAppl_Del.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 표준코드신청 정보가 없습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name setGrdTitle
 * @description 그리드 타이틀 세팅.
 * @param {*} pFg pFg
 * @returns {void}
 * @hidden N
 */
scwin.setGrdTitle = function(pFg) {
    if (pFg === "ins_Search") {
        $c.cm.setColumnProp(grd_FaxLink, "ROWCNT", "Name", dts_FaxLink.getRowCount() + "건");
    } else if (pFg === "ins_Search1") {
        $c.cm.setColumnProp(grd_IsurAppl, "ROWCNT", "Name", dts_IsurAppl.getRowCount() + "건");
    } else if (pFg === "ins_Search2") {
        $c.cm.setColumnProp(grd_StdCdAppl, "ROWCNT", "Name", dts_StdCdAppl.getRowCount() + "건");
    } else if (pFg === "ins_Search3") {
        $c.cm.setColumnProp(grd_DownIp, "ROWCNT", "Name", dts_DownIp.getRowCount() + "건");
    } else if (pFg === "ins_Search4") {
        $c.cm.setColumnProp(grd_StdCdAppl_Del, "ROWCNT", "Name", dts_StdCdAppl_Del.getRowCount() + "건");
    }
};

